base=next(r for r in s['stages'] if 'base_contact ↔ motor_contact' in r['name']);screw=next(r for r in s['stages'] if 'male_contact ↔ driver_case_front' in r['name']);total=s['stage_narrow_s'];supp=base['supplement_ns']/1e9
